import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

results = []

for b in range(1, 11):
    # Equation: a^2 - a(2^(b+1)-1) + 2 * 3^b = 0

    C_b = (2**(b + 1)) - 1
    D_b = 2 * (3**b)

    # Discriminant: Delta = C_b^2 - 4 * D_b
    delta = C_b**2 - 4 * D_b

    if is_perfect_square(delta):
        m = math.isqrt(delta)

        # Solutions for a: a = (C_b +/- m) / 2

        # Solution 1
        numerator1 = C_b + m
        if numerator1 % 2 == 0:
            a1 = numerator1 // 2
            if a1 > 0:
                results.append((a1, b, a1 + b))

        # Solution 2
        numerator2 = C_b - m
        if numerator2 % 2 == 0:
            a2 = numerator2 // 2
            if a2 > 0:
                # Avoid adding the same solution twice if m=0 or a1=a2
                if a2 != a1:
                    results.append((a2, b, a2 + b))

# Print results in a structured way
print("--- Solutions (a, b, a+b) ---")
for a, b, a_plus_b in results:
    print(f"({a}, {b}), Sum: {a_plus_b}")

# Collect all unique (a, b) pairs and their sums
final_list = {}
for a, b, a_plus_b in results:
    key = (a, b)
    if key not in final_list:
        final_list[key] = a_plus_b

print("\n--- Final Record ---")
print(final_list)

def calculate_delta(b):
    # Delta = (2^(b+1) - 1)^2 - 8 * 3^b
    term1 = (2**(b+1) - 1)**2
    term2 = 8 * (3**b)
    delta = term1 - term2
    return delta

for b in range(1, 10):
    delta = calculate_delta(b)
    print(f"b={b}: Delta = {delta}")
    if delta >= 0:
        import math
        sqrt_delta = math.isqrt(delta)
        if sqrt_delta * sqrt_delta == delta:
            print(f"  Perfect Square: Yes (sqrt={sqrt_delta})")
        else:
            print(f"  Perfect Square: No")

